// Runs first on every page of the GitHub Pages demo (see snapshot.mjs). It replays the
// JSON recorded from the real app, refuses anything that would save, turns in-app
// navigation into plain page loads, and shows a small "demo" banner.
(function () {
  var D = window.__DEMO__;
  var BASE = D.basePath;
  var queryMap = new Map(D.queryRoutes);

  function json(body, status) {
    return new Response(typeof body === "string" ? body : JSON.stringify(body), { status: status || 200, headers: { "Content-Type": "application/json" } });
  }
  var READ_ONLY = { error: { code: "DEMO", message: "This is a read-only demo — nothing is saved. Run the app locally to try this." } };

  function route(u) {
    var p = u.pathname.indexOf(BASE) === 0 ? u.pathname.slice(BASE.length) : u.pathname;
    return p || "/";
  }

  var realFetch = window.fetch.bind(window);
  window.fetch = function (input, init) {
    var url = new URL(typeof input === "string" ? input : input.url, location.href);
    var method = ((init && init.method) || (input && input.method) || "GET").toUpperCase();
    var r = route(url);
    if (url.origin !== location.origin || r.indexOf("/api/") !== 0) return realFetch(input, init);

    if (method === "GET") {
      var hit = D.api["GET " + r + url.search];
      if (hit) return Promise.resolve(json(hit.body, hit.status));
      var q = (url.searchParams.get("q") || "").toLowerCase().split(/\s+/).filter(Boolean);
      var match = function (fields) {
        var hay = fields.join(" ").toLowerCase();
        return q.length > 0 && q.every(function (t) { return hay.indexOf(t) >= 0; });
      };
      if (r === "/api/products/search")
        return Promise.resolve(json({ items: D.catalog.filter(function (p) { return match([p.name, p.sku, p.partNumber || "", p.brand || "", p.category || "", p.models.join(" "), p.barcodes.join(" ")]); }).slice(0, 12) }));
      if (r === "/api/customers/search")
        return Promise.resolve(json({ items: D.customers.filter(function (c) { return match([c.name, c.code, c.phone || "", c.bikes.join(" ")]); }).slice(0, 10) }));
      if (/\/search$|\/lookup$/.test(r)) return Promise.resolve(json({ items: [] }));
      return Promise.resolve(json({ error: { code: "DEMO", message: "Not recorded in the demo." } }, 404));
    }
    var body = {};
    try {
      body = JSON.parse((init && init.body) || "{}");
    } catch (e) {}
    if (r === "/api/auth/login") return Promise.resolve(json({ user: { id: "demo", name: "Prakash", role: "OWNER" } }));
    // Printing is a recorded read: show the saved bill, but say it is not a new print run.
    var print = D.api["POST " + r];
    if (print && /^\/api\/invoices\/[^/]+\/print$/.test(r)) return Promise.resolve(json(print.body, print.status));
    if (r === "/api/auth/logout") return Promise.resolve(json({ ok: true }));
    if (r === "/api/assistant") {
      var a = D.assistant[String(body.text || "").trim().toLowerCase()];
      if (a) return Promise.resolve(json(a));
      return Promise.resolve(
        json({
          engine: "Demo",
          reply: "The demo can only replay the suggested questions. The real app answers anything from the shop's records. Try: " + Object.keys(D.assistant).slice(0, 4).join(" · "),
          blocks: [],
        }),
      );
    }
    return Promise.resolve(json(READ_ONLY, 403));
  };

  function staticUrl(href) {
    var u = new URL(href, location.href);
    var r = route(u);
    var full = r + u.search;
    if (u.search && queryMap.has(full)) return BASE + queryMap.get(full);
    return BASE + (r === "/" ? "/dashboard" : r).replace(/\/$/, "") + "/";
  }

  // A query-string URL loaded directly (or by a hard navigation) → its saved copy.
  if (location.search && queryMap.has(route(location) + location.search)) location.replace(BASE + queryMap.get(route(location) + location.search));

  // The app's client-side router expects a server; plain page loads work everywhere.
  document.addEventListener(
    "click",
    function (e) {
      var a = e.target && e.target.closest && e.target.closest("a[href]");
      if (!a || a.target === "_blank" || a.hasAttribute("download") || e.ctrlKey || e.metaKey || e.shiftKey || e.button !== 0) return;
      var u = new URL(a.getAttribute("href"), location.href);
      if (u.origin !== location.origin || route(u).indexOf("/api/") === 0) {
        if (route(u).indexOf("/api/") === 0) {
          e.preventDefault();
          alert(READ_ONLY.error.message);
        }
        return;
      }
      e.preventDefault();
      e.stopPropagation();
      location.assign(staticUrl(u.href));
    },
    true,
  );
  var push = history.pushState;
  history.pushState = function (s, t, url) {
    if (url && new URL(url, location.href).pathname !== location.pathname) return location.assign(staticUrl(String(url)));
    return push.apply(this, arguments);
  };

  window.addEventListener("load", function () {
    var bar = document.createElement("div");
    bar.setAttribute("style", "position:fixed;left:50%;bottom:12px;transform:translateX(-50%);z-index:70;background:#0f172a;color:#fff;font:500 12px/1.4 system-ui,sans-serif;padding:6px 12px;border-radius:999px;box-shadow:0 4px 14px rgba(0,0,0,.2);pointer-events:none;white-space:nowrap");
    bar.textContent = "Demo · read-only snapshot of sample data · " + D.builtAt.slice(0, 10);
    document.documentElement.appendChild(bar);
  });
})();
